"""Graph utilities for shortest-path and reachability analysis."""
from typing import Dict, List, Tuple, Optional, Set
from dataclasses import dataclass
import heapq
from collections import deque

@dataclass
class Edge:
    src: int
    dst: int
    weight: float

class WeightedGraph:
    """Adjacency-list weighted directed graph."""
    def __init__(self):
        self.adj: Dict[int, List[Tuple[int, float]]] = {}
        self._edges: List[Edge] = []
        self._node_data: Dict[int, dict] = {}

    def add_node(self, node_id: int, **data):
        if node_id not in self.adj:
            self.adj[node_id] = []
        self._node_data[node_id] = data

    def add_edge(self, src: int, dst: int, weight: float = 1.0):
        self.add_node(src)
        self.add_node(dst)
        self.adj[src].append((dst, weight))
        self._edges.append(Edge(src, dst, weight))

    @property
    def nodes(self) -> Set[int]:
        return set(self.adj.keys())

    @property
    def edge_count(self) -> int:
        return len(self._edges)

    def neighbors(self, node: int) -> List[Tuple[int, float]]:
        return self.adj.get(node, [])

    def node_data(self, node: int) -> dict:
        return self._node_data.get(node, {})


def _dijkstra(
    graph: WeightedGraph,
    source: int,
    target: Optional[int] = None,
    k: Optional[int] = None,
) -> Tuple[Dict[int, float], Dict[int, Optional[int]]]:
    """
    Core Dijkstra implementation shared by public API functions.

    Complexity: O((V + E) log V)

    Args:
        graph:  The weighted directed graph to search.
        source: Starting node.
        target: If provided, stop as soon as this node is settled (used by
                shortest_path / is_reachable to avoid processing the entire
                graph when only a single destination is needed).
        k:      If provided, stop after k nodes beyond the source have been
                settled (used by k_nearest for early termination).

    Returns:
        dist – mapping from node → best known distance from source.
        prev – mapping from node → predecessor on the shortest-path tree
               (None for the source and for unreached nodes).
    """
    nodes = graph.nodes
    dist: Dict[int, float] = {n: float('inf') for n in nodes}
    prev: Dict[int, Optional[int]] = {n: None for n in nodes}
    dist[source] = 0.0

    # Min-heap entries: (distance, node).
    # We use a lazy-deletion strategy: if we pop a stale entry (one whose
    # recorded distance is larger than the current best) we simply skip it.
    heap: List[Tuple[float, int]] = [(0.0, source)]
    settled: int = 0  # counts nodes popped and processed (excluding source)

    while heap:
        d, u = heapq.heappop(heap)

        # Stale entry — a shorter path to u was already processed.
        if d > dist[u]:
            continue

        # Early-exit: single-target mode.
        if target is not None and u == target:
            break

        # Early-exit: k-nearest mode (source itself is not counted).
        if k is not None and u != source:
            settled += 1
            if settled >= k:
                break

        # Relax outgoing edges using the adjacency list — O(deg(u) log V).
        for v, w in graph.adj.get(u, []):
            nd = dist[u] + w
            if nd < dist[v]:
                dist[v] = nd
                prev[v] = u
                heapq.heappush(heap, (nd, v))

    return dist, prev


def _reconstruct_path(prev: Dict[int, Optional[int]], target: int) -> List[int]:
    """Walk the predecessor map back from target to build the path list."""
    path: List[int] = []
    current: Optional[int] = target
    while current is not None:
        path.append(current)
        current = prev[current]
    path.reverse()
    return path


def shortest_path(
    graph: WeightedGraph, source: int, target: int
) -> Tuple[Optional[float], List[int]]:
    """Find shortest path from source to target.

    Returns (distance, path) or (None, []) if unreachable.

    Complexity: O((V + E) log V)
    """
    nodes = graph.nodes
    if source not in nodes or target not in nodes:
        return None, []

    # Use target-early-exit to avoid settling every node when possible.
    dist, prev = _dijkstra(graph, source, target=target)

    if dist[target] == float('inf'):
        return None, []

    return dist[target], _reconstruct_path(prev, target)


def all_shortest_paths(
    graph: WeightedGraph, source: int
) -> Dict[int, Tuple[float, List[int]]]:
    """Find shortest paths from source to all reachable nodes.

    Returns {node: (distance, path)}.

    Complexity: O((V + E) log V)  — single Dijkstra pass over the whole graph.
    """
    nodes = graph.nodes
    if source not in nodes:
        return {}

    dist, prev = _dijkstra(graph, source)

    result: Dict[int, Tuple[float, List[int]]] = {}
    for node in nodes:
        if node == source:
            result[node] = (0.0, [source])
        elif dist[node] < float('inf'):
            result[node] = (dist[node], _reconstruct_path(prev, node))

    return result


def k_nearest(
    graph: WeightedGraph, source: int, k: int
) -> List[Tuple[int, float]]:
    """Find k nearest nodes to source by shortest-path distance.

    Returns list of (node_id, distance) sorted by distance.

    Complexity: O((k + E) log V) in the best case; O((V + E) log V) worst case.

    Because Dijkstra settles nodes in non-decreasing distance order, we can
    stop as soon as k nodes (other than the source) have been settled — those
    are guaranteed to be the k closest.
    """
    nodes = graph.nodes
    if source not in nodes or k <= 0:
        return []

    dist: Dict[int, float] = {n: float('inf') for n in nodes}
    dist[source] = 0.0

    heap: List[Tuple[float, int]] = [(0.0, source)]
    result: List[Tuple[int, float]] = []

    while heap and len(result) < k:
        d, u = heapq.heappop(heap)

        if d > dist[u]:
            continue  # stale entry

        if u != source:
            result.append((u, d))
            if len(result) == k:
                break

        for v, w in graph.adj.get(u, []):
            nd = dist[u] + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(heap, (nd, v))

    return result


def is_reachable(graph: WeightedGraph, source: int, target: int) -> bool:
    """Check if target is reachable from source.

    Complexity: O(V + E)  — plain BFS, no weights needed.
    """
    if source not in graph.adj or target not in graph.adj:
        return False
    if source == target:
        return True

    visited: Set[int] = {source}
    queue: deque[int] = deque([source])

    while queue:
        u = queue.popleft()
        for v, _ in graph.adj.get(u, []):
            if v == target:
                return True
            if v not in visited:
                visited.add(v)
                queue.append(v)

    return False


def connected_components(graph: WeightedGraph) -> List[Set[int]]:
    """Find weakly connected components (treating edges as undirected).

    Returns a list of sets, each set containing the node IDs of one component.

    Complexity: O(V + E)  — builds an undirected adjacency list once, then
    runs a straightforward BFS from every unvisited node.
    """
    nodes = graph.nodes

    # Build an undirected neighbour map in O(V + E).
    undirected: Dict[int, Set[int]] = {n: set() for n in nodes}
    for edge in graph._edges:
        undirected[edge.src].add(edge.dst)
        undirected[edge.dst].add(edge.src)

    visited: Set[int] = set()
    components: List[Set[int]] = []

    for start in nodes:
        if start in visited:
            continue

        # BFS to collect the entire weakly-connected component.
        component: Set[int] = set()
        queue: deque[int] = deque([start])
        visited.add(start)

        while queue:
            u = queue.popleft()
            component.add(u)
            for v in undirected.get(u, set()):
                if v not in visited:
                    visited.add(v)
                    queue.append(v)

        components.append(component)

    return components
